local ADDON, ns = ...
-- NeedleDropper Sets: the soundtracks that ship inside the addon.
--
-- Sets\*.lua are generated by tools/gen_sets.py from packs/*.json (contract:
-- docs/SETS-FORMAT.md). Each file calls ns.RegisterBuiltinSet{...} once while the client loads
-- the addon's files, before SavedVariables exist, so this file only checks and stores the
-- tables; everything per account or character happens later in Soundtracks.lua.
--
--   ns.RegisterBuiltinSet(set) -> true | false, message
--       Accepts format version 1 only, refuses a second set with the same id, keeps a private
--       copy (later changes to the caller's table do not reach it). A rejected set is reported
--       once in chat at login.
--   ns.Sets.Builtins()      -> array of copies of every built-in set, in registration order
--   ns.Sets.GetBuiltin(id)  -> copy of one built-in set, or nil
--   ns.Sets.Has(id), ns.Sets.Ids(), ns.Sets.Count()
--   ns.Sets.DefaultId()     -> the id of the default soundtrack: the first set tagged
--                              "default" (SETS-FORMAT), else azeroth-mixtape, else the first
--   ns.Sets.Problems()      -> messages about sets or drops that were not accepted
--   ns.Sets.Internal(id)    -> the stored table itself, for Soundtracks.lua / Share.lua only.
--                              Read-only: never change it or anything inside it.
--
-- Lua 5.1 has no __len / __pairs metamethods, so a read-only proxy would break #set.drops and
-- ipairs; the tables are frozen by copying instead (a copy in, a copy out).

local Sets = {}
ns.Sets = Sets

local L = ns.L or setmetatable({}, { __index = function(_, k) return k end })

local type, pairs, tostring = type, pairs, tostring
local floor, huge = math.floor, math.huge
local find, format = string.find, string.format

Sets.FORMAT_VERSION = 1
Sets.DEFAULT_TAG = "default"
Sets.FALLBACK_DEFAULT = "azeroth-mixtape"
Sets.MAX_ID = 40

local order = {}      -- set ids in registration order
local byId = {}       -- set id -> stored (private) table
local problems = {}   -- messages for sets / drops that were not accepted
local reported = 0    -- how many problems were already printed

local KINDS = { zone = true, subzone = true, instance = true }
local SET_TEXT = { "name", "author", "description", "source", "homepage" }
local DROP_TEXT = { "subzone", "label", "title", "artist", "youtube", "spotify", "note" }
local DROP_PLACE_NUMBERS = { "mapID", "areaID", "instanceID" }
local DROP_TIME_NUMBERS = { "startMs", "durationMs" }
local MAX_NUMBER = 2147483647

-- ------------------------------------------------------------------ helpers --

local function copy(v)
  if type(v) ~= "table" then return v end
  local out = {}
  for k, x in pairs(v) do out[k] = copy(x) end
  return out
end
Sets.Copy = copy

local function isInt(v)
  return type(v) == "number" and v == v and v ~= huge and v ~= -huge and floor(v) == v
end

-- A set id: 1-40 of a-z, 0-9 and "-", with at least one letter or digit.
function Sets.IsValidId(id)
  return type(id) == "string" and #id >= 1 and #id <= Sets.MAX_ID and find(id, "^[a-z0-9%-]+$") ~= nil
    and find(id, "[a-z0-9]") ~= nil
end

local function problem(message)
  problems[#problems + 1] = message
end

local function describeSet(set)
  if type(set) == "table" then
    if type(set.id) == "string" then return set.id end
    if type(set.source) == "string" then return set.source end
  end
  return "?"
end

-- Array of distinct non-empty strings, or nil when there are none.
local function cleanTags(tags)
  if type(tags) ~= "table" then return nil end
  local out, seen = {}, {}
  for i = 1, #tags do
    local t = tags[i]
    if type(t) == "string" and t ~= "" and not seen[t] then
      seen[t] = true
      out[#out + 1] = t
    end
  end
  if #out == 0 then return nil end
  return out
end

-- Checked copy of one generated drop, or nil plus the reason.
local function cleanDrop(d)
  if type(d) ~= "table" then return nil, "not a table" end
  if type(d.id) ~= "string" or d.id == "" then return nil, "no id" end
  if not KINDS[d.kind] then return nil, "unknown kind " .. tostring(d.kind) end
  local out = { id = d.id, kind = d.kind }
  for i = 1, #DROP_PLACE_NUMBERS do
    local k = DROP_PLACE_NUMBERS[i]
    local v = d[k]
    if v ~= nil then
      if not isInt(v) or v < 1 or v > MAX_NUMBER then return nil, "bad " .. k end
      out[k] = v
    end
  end
  for i = 1, #DROP_TIME_NUMBERS do
    local k = DROP_TIME_NUMBERS[i]
    local v = d[k]
    if v ~= nil then
      if not isInt(v) or v < 0 or v > MAX_NUMBER then return nil, "bad " .. k end
      out[k] = v
    end
  end
  for i = 1, #DROP_TEXT do
    local k = DROP_TEXT[i]
    local v = d[k]
    if v ~= nil then
      if type(v) ~= "string" then return nil, "bad " .. k end
      if v ~= "" then out[k] = v end
    end
  end
  if not out.title or not out.artist then return nil, "no title or artist" end
  if out.kind == "zone" and not out.mapID then return nil, "zone drop without mapID" end
  if out.kind == "subzone" and not (out.areaID or (out.mapID and out.subzone)) then
    return nil, "landmark drop without areaID or mapID + subzone"
  end
  if out.kind == "instance" and not out.instanceID then return nil, "instance drop without instanceID" end
  if not out.label then out.label = out.subzone or out.id end
  out.tags = cleanTags(d.tags)
  return out
end

-- ------------------------------------------------------------- registration --

function ns.RegisterBuiltinSet(set)
  local name = describeSet(set)
  if type(set) ~= "table" then
    local msg = format(L["Built-in soundtrack %s was not loaded: %s"], name, L["it is not a table."])
    problem(msg)
    return false, msg
  end
  local version = set.version
  if version ~= Sets.FORMAT_VERSION then
    local msg
    if type(version) == "number" and version > Sets.FORMAT_VERSION then
      msg = format(L["Built-in soundtrack %s needs a newer NeedleDropper (set format %s); it was skipped."],
        name, tostring(version))
    else
      msg = format(L["Built-in soundtrack %s was not loaded: %s"], name,
        format(L["unsupported set format %s."], tostring(version)))
    end
    problem(msg)
    return false, msg
  end
  if not Sets.IsValidId(set.id) then
    local msg = format(L["Built-in soundtrack %s was not loaded: %s"], name, L["its id is not valid."])
    problem(msg)
    return false, msg
  end
  if byId[set.id] then
    local msg = format(L["Built-in soundtrack %s was loaded twice; the second copy was ignored."], set.id)
    problem(msg)
    return false, msg
  end
  if type(set.drops) ~= "table" then
    local msg = format(L["Built-in soundtrack %s was not loaded: %s"], name, L["it has no drops."])
    problem(msg)
    return false, msg
  end

  local stored = { id = set.id, version = version, tags = cleanTags(set.tags) or {} }
  for i = 1, #SET_TEXT do
    local k = SET_TEXT[i]
    if type(set[k]) == "string" then stored[k] = set[k] end
  end
  if not stored.name or stored.name == "" then stored.name = set.id end
  stored.author = stored.author or ""
  stored.description = stored.description or ""
  stored.source = stored.source or ""
  if stored.homepage == "" then stored.homepage = nil end

  local drops, seen = {}, {}
  for i = 1, #set.drops do
    local d, why = cleanDrop(set.drops[i])
    if not d then
      problem(format(L["Built-in soundtrack %s: drop %d was skipped (%s)."], set.id, i, why))
    elseif seen[d.id] then
      problem(format(L["Built-in soundtrack %s: drop %s appears twice; the second one was skipped."], set.id, d.id))
    else
      seen[d.id] = true
      drops[#drops + 1] = d
    end
  end
  if #drops == 0 then
    local msg = format(L["Built-in soundtrack %s was not loaded: %s"], name, L["it has no drops."])
    problem(msg)
    return false, msg
  end
  stored.drops = drops

  byId[set.id] = stored
  order[#order + 1] = set.id
  return true
end

-- ---------------------------------------------------------------- queries --

function Sets.Builtins()
  local out = {}
  for i = 1, #order do out[i] = copy(byId[order[i]]) end
  return out
end

function Sets.GetBuiltin(id)
  local s = byId[id]
  if not s then return nil end
  return copy(s)
end

function Sets.Internal(id)
  return byId[id]
end

function Sets.Has(id)
  return byId[id] ~= nil
end

function Sets.Ids()
  local out = {}
  for i = 1, #order do out[i] = order[i] end
  return out
end

function Sets.Count()
  return #order
end

function Sets.DefaultId()
  for i = 1, #order do
    local tags = byId[order[i]].tags
    for j = 1, #tags do
      if tags[j] == Sets.DEFAULT_TAG then return order[i] end
    end
  end
  if byId[Sets.FALLBACK_DEFAULT] then return Sets.FALLBACK_DEFAULT end
  return order[1]
end

function Sets.Problems()
  local out = {}
  for i = 1, #problems do out[i] = problems[i] end
  return out
end

-- A broken built-in set is a packaging bug: say so once, at login, so it gets reported.
if ns.On then
  ns.On("PLAYER_LOGIN", function()
    for i = reported + 1, #problems do
      if ns.Print then ns.Print("%s", problems[i]) end
    end
    reported = #problems
  end)
end

return Sets
